package com.example.back.config;

import org.springframework.context.annotation.Configuration;
import org.springframework.web.socket.config.annotation.EnableWebSocket;
import org.springframework.web.socket.config.annotation.WebSocketConfigurer;
import org.springframework.web.socket.config.annotation.WebSocketHandlerRegistry;
import org.springframework.beans.factory.annotation.Autowired;
import com.example.back.websocket.VoiceMailWebSocketHandler;

@Configuration
@EnableWebSocket
public class WebSocketConfig implements WebSocketConfigurer {

    @Autowired
    private VoiceMailWebSocketHandler voiceMailWebSocketHandler;

    @Override
    public void registerWebSocketHandlers(WebSocketHandlerRegistry registry) {
        // Registra o handler para conexões WebSocket na rota /ws/voicemails
        registry.addHandler(voiceMailWebSocketHandler, "/ws/voicemails")
                .setAllowedOrigins("*");
    }
}

package com.example.back.controller;

import com.example.back.websocket.VoiceMailWebSocketHandler;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

import java.util.HashMap;
import java.util.Map;

@RestController
@RequestMapping("/api/websocket")
public class WebSocketInfoController {

    @Autowired
    private VoiceMailWebSocketHandler webSocketHandler;

    @GetMapping("/status")
    public ResponseEntity<Map<String, Object>> getWebSocketStatus() {
        Map<String, Object> status = new HashMap<>();
        status.put("connected", true);
        status.put("activeConnections", webSocketHandler.getActiveConnectionCount());
        status.put("wsUrl", "ws://localhost:8080/ws/voicemails");

        return ResponseEntity.ok(status);
    }
}

package com.example.back.service;

import com.example.back.dtos.Output.VoiceMailResponse;
import com.example.back.websocket.VoiceMailWebSocketHandler;
import com.fasterxml.jackson.databind.ObjectMapper;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

@Slf4j
@Service
public class WebSocketNotificationService {

    @Autowired
    private VoiceMailWebSocketHandler webSocketHandler;

    private final ObjectMapper objectMapper = new ObjectMapper();

    /**
     * Notifica todos os clientes sobre um novo voicemail
     */
    public void notifyNewVoiceMail(VoiceMailResponse voicemail) {
        try {
            String message = objectMapper.writeValueAsString(new WebSocketMessage(
                    "NEW_VOICEMAIL",
                    "Um novo correio de voz foi adicionado",
                    voicemail
            ));
            webSocketHandler.broadcast(message);
        } catch (Exception e) {
            log.error("Erro ao notificar novo voicemail", e);
        }
    }

    /**
     * Notifica todos os clientes sobre atualização de status de voicemail
     */
    public void notifyVoiceMailStatusUpdated(Long voiceMailId, Boolean ouvido) {
        try {
            String message = objectMapper.writeValueAsString(new WebSocketMessage(
                    "VOICEMAIL_UPDATED",
                    "Status do correio de voz foi atualizado",
                    new VoiceMailStatusUpdate(voiceMailId, ouvido)
            ));
            webSocketHandler.broadcast(message);
        } catch (Exception e) {
            log.error("Erro ao notificar atualização de voicemail", e);
        }
    }

    /**
     * Notifica todos os clientes sobre exclusão de voicemail
     */
    public void notifyVoiceMailDeleted(Long voiceMailId) {
        try {
            String message = objectMapper.writeValueAsString(new WebSocketMessage(
                    "VOICEMAIL_DELETED",
                    "Correio de voz foi removido",
                    new VoiceMailDeletedUpdate(voiceMailId)
            ));
            webSocketHandler.broadcast(message);
        } catch (Exception e) {
            log.error("Erro ao notificar exclusão de voicemail", e);
        }
    }

    /**
     * Classe interna para estrutura de mensagem WebSocket
     */
    public static class WebSocketMessage {
        public String type;
        public String message;
        public Object data;

        public WebSocketMessage(String type, String message, Object data) {
            this.type = type;
            this.message = message;
            this.data = data;
        }
    }

    /**
     * Classe para atualização de status
     */
    public static class VoiceMailStatusUpdate {
        public Long voiceMailId;
        public Boolean ouvido;

        public VoiceMailStatusUpdate(Long voiceMailId, Boolean ouvido) {
            this.voiceMailId = voiceMailId;
            this.ouvido = ouvido;
        }
    }

    /**
     * Classe para exclusão
     */
    public static class VoiceMailDeletedUpdate {
        public Long voiceMailId;

        public VoiceMailDeletedUpdate(Long voiceMailId) {
            this.voiceMailId = voiceMailId;
        }
    }
}

package com.example.back.service.impl;

import com.example.back.dtos.Input.VoiceMailRequest;
import com.example.back.dtos.Output.VoiceMailResponse;
import com.example.back.mapper.VoiceMailMapper;
import com.example.back.persistence.entity.VoiceMail;
import com.example.back.persistence.repository.VoiceMailRepository;
import com.example.back.service.VoiceMailService;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import org.springframework.web.multipart.MultipartFile;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.List;

@Service
@RequiredArgsConstructor
public class VoiceMailServiceImpl implements VoiceMailService {

    private final VoiceMailRepository repository;

    private final VoiceMailMapper mapper;

    private static final String DIRETORIO_UPLOAD = "uploads/audio/";


    @Override
    public VoiceMailResponse criar(VoiceMailRequest dto) {
        VoiceMail entity = mapper.toEntity(dto);

        VoiceMail salvo = repository.save(entity);

        return mapper.toResponse(salvo);
    }

    @Override
    public List<VoiceMailResponse> listar() {
        return repository.findAll()
                .stream()
                .map(mapper::toResponse)
                .toList();
    }

    @Override
    public VoiceMailResponse buscarPorId(Long id) {
        VoiceMail entity = repository.findById(id)
                .orElseThrow(() -> new RuntimeException("VoiceMail não encontrado"));

        return mapper.toResponse(entity);
    }

    @Override
    public void marcarComoOuvido(Long id) {
        VoiceMail entity = repository.findById(id)
                .orElseThrow(() -> new RuntimeException("VoiceMail não encontrado"));

        entity.setOuvido(true);

        repository.save(entity);
    }

    @Override
    public void deletar(Long id) {
        if (!repository.existsById(id)) {
            throw new RuntimeException("VoiceMail não encontrado");
        }

        repository.deleteById(id);
    }

    @Override
    public List<VoiceMailResponse> listarNaoOuvidos() {
        return repository.findAll()
                .stream()
                .filter(vm -> vm.getOuvido() == false)
                .map(mapper::toResponse)
                .toList();
    }
    @Override
    public VoiceMailRequest processarUploadDeAudio(MultipartFile arquivo, String transcricao) throws IOException {
        validarArquivo(arquivo);

        Path caminhoUpload = Paths.get(DIRETORIO_UPLOAD);
        criarDiretorioSeNaoExistir(caminhoUpload);

        String nomeArquivo = gerarNomeArquivo(arquivo.getOriginalFilename());
        Path caminhoCompleto = caminhoUpload.resolve(nomeArquivo);

        salvarArquivo(arquivo, caminhoCompleto);

        String urlAudio = "/audio/" + nomeArquivo;

        return new VoiceMailRequest(transcricao, urlAudio);
    }

    private void validarArquivo(MultipartFile arquivo) {
        if (arquivo.isEmpty()) {
            throw new IllegalArgumentException("O arquivo não pode estar vazio");
        }
    }

    private void criarDiretorioSeNaoExistir(Path caminho) throws IOException {
        if (!Files.exists(caminho)) {
            Files.createDirectories(caminho);
        }
    }

    private String gerarNomeArquivo(String nomeOriginal) {
        return System.currentTimeMillis() + "_" + nomeOriginal;
    }

    private void salvarArquivo(MultipartFile arquivo, Path caminho) throws IOException {
        Files.copy(arquivo.getInputStream(), caminho);
    }
}

package com.example.back.service.impl;

import com.example.back.dtos.Input.VoiceMailRequest;
import com.example.back.dtos.Output.VoiceMailResponse;
import com.example.back.mapper.VoiceMailMapper;
import com.example.back.persistence.entity.VoiceMail;
import com.example.back.persistence.repository.VoiceMailRepository;
import com.example.back.service.VoiceMailService;
import com.example.back.service.WebSocketNotificationService;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import org.springframework.web.multipart.MultipartFile;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.List;

@Service
@RequiredArgsConstructor
public class VoiceMailServiceImpl implements VoiceMailService {

    private final VoiceMailRepository repository;
    private final VoiceMailMapper mapper;
    private final WebSocketNotificationService notificationService;

    private static final String DIRETORIO_UPLOAD = "uploads/audio/";


    @Override
    public VoiceMailResponse criar(VoiceMailRequest dto) {
        VoiceMail entity = mapper.toEntity(dto);

        VoiceMail salvo = repository.save(entity);
        VoiceMailResponse response = mapper.toResponse(salvo);

        // Notifica todos os clientes sobre o novo voicemail
        notificationService.notifyNewVoiceMail(response);

        return response;
    }

    @Override
    public List<VoiceMailResponse> listar() {
        return repository.findAll()
                .stream()
                .map(mapper::toResponse)
                .toList();
    }

    @Override
    public VoiceMailResponse buscarPorId(Long id) {
        VoiceMail entity = repository.findById(id)
                .orElseThrow(() -> new RuntimeException("VoiceMail não encontrado"));

        return mapper.toResponse(entity);
    }

    @Override
    public void marcarComoOuvido(Long id) {
        VoiceMail entity = repository.findById(id)
                .orElseThrow(() -> new RuntimeException("VoiceMail não encontrado"));

        entity.setOuvido(true);

        repository.save(entity);

        // Notifica todos os clientes sobre a atualização
        notificationService.notifyVoiceMailStatusUpdated(id, true);
    }

    @Override
    public void deletar(Long id) {
        if (!repository.existsById(id)) {
            throw new RuntimeException("VoiceMail não encontrado");
        }

        repository.deleteById(id);

        // Notifica todos os clientes sobre a exclusão
        notificationService.notifyVoiceMailDeleted(id);
    }

    @Override
    public List<VoiceMailResponse> listarNaoOuvidos() {
        return repository.findAll()
                .stream()
                .filter(vm -> vm.getOuvido() == false)
                .map(mapper::toResponse)
                .toList();
    }
    @Override
    public VoiceMailRequest processarUploadDeAudio(MultipartFile arquivo, String transcricao) throws IOException {
        validarArquivo(arquivo);

        Path caminhoUpload = Paths.get(DIRETORIO_UPLOAD);
        criarDiretorioSeNaoExistir(caminhoUpload);

        String nomeArquivo = gerarNomeArquivo(arquivo.getOriginalFilename());
        Path caminhoCompleto = caminhoUpload.resolve(nomeArquivo);

        salvarArquivo(arquivo, caminhoCompleto);

        String urlAudio = "/audio/" + nomeArquivo;

        return new VoiceMailRequest(transcricao, urlAudio);
    }

    private void validarArquivo(MultipartFile arquivo) {
        if (arquivo.isEmpty()) {
            throw new IllegalArgumentException("O arquivo não pode estar vazio");
        }
    }

    private void criarDiretorioSeNaoExistir(Path caminho) throws IOException {
        if (!Files.exists(caminho)) {
            Files.createDirectories(caminho);
        }
    }

    private String gerarNomeArquivo(String nomeOriginal) {
        return System.currentTimeMillis() + "_" + nomeOriginal;
    }

    private void salvarArquivo(MultipartFile arquivo, Path caminho) throws IOException {
        Files.copy(arquivo.getInputStream(), caminho);
    }
}

package com.example.back.websocket;

import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Component;
import org.springframework.web.socket.CloseStatus;
import org.springframework.web.socket.TextMessage;
import org.springframework.web.socket.WebSocketSession;
import org.springframework.web.socket.handler.TextWebSocketHandler;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.io.IOException;
import java.util.concurrent.CopyOnWriteArraySet;

@Slf4j
@Component
public class VoiceMailWebSocketHandler extends TextWebSocketHandler {

    // Set thread-safe para armazenar todas as sessões conectadas
    private static final CopyOnWriteArraySet<WebSocketSession> sessions = new CopyOnWriteArraySet<>();
    private final ObjectMapper objectMapper = new ObjectMapper();

    @Override
    public void afterConnectionEstablished(WebSocketSession session) throws Exception {
        sessions.add(session);
        log.info("Nova conexão WebSocket estabelecida. Total: {}", sessions.size());

        // Envia mensagem de confirmação ao cliente
        session.sendMessage(new TextMessage("{\"type\":\"CONNECTED\",\"message\":\"Conectado ao servidor de voicemails\"}"));
    }

    @Override
    protected void handleTextMessage(WebSocketSession session, TextMessage message) throws Exception {
        try {
            String payload = message.getPayload();
            log.debug("Mensagem recebida: {}", payload);

            // Aqui você pode processar mensagens do cliente se necessário
            // Por enquanto, apenas registramos a mensagem

        } catch (Exception e) {
            log.error("Erro ao processar mensagem WebSocket", e);
            session.sendMessage(new TextMessage("{\"type\":\"ERROR\",\"message\":\"Erro ao processar mensagem\"}"));
        }
    }

    @Override
    public void afterConnectionClosed(WebSocketSession session, CloseStatus status) throws Exception {
        sessions.remove(session);
        log.info("Conexão WebSocket fechada. Total: {}", sessions.size());
    }

    /**
     * Envia uma mensagem para todos os clientes conectados
     */
    public void broadcast(String message) {
        log.debug("Enviando broadcast para {} sessões", sessions.size());

        for (WebSocketSession session : sessions) {
            if (session.isOpen()) {
                try {
                    session.sendMessage(new TextMessage(message));
                } catch (IOException e) {
                    log.error("Erro ao enviar mensagem para sessão", e);
                }
            }
        }
    }

    /**
     * Obtém o número de conexões ativas
     */
    public int getActiveConnectionCount() {
        return sessions.size();
    }
}

/**
 * EXEMPLO DE COMO INTEGRAR O WEBSOCKET NO COMPONENTE INBOX
 * 
 * Este arquivo mostra como usar o hook useVoiceMailWebSocket
 * para sincronização em tempo real no seu componente Inbox.jsx
 * 
 * Para usar, substitua o trecho no seu Inbox.jsx:
 */

import { useEffect, useMemo, useState } from "react";
import Recorder from "./Recorder";
import useVoiceMailWebSocket from "../hooks/useVoiceMailWebSocket";
import {
    listarVoicemails,
    marcarComoOuvido,
    deletarVoicemail,
} from "../services/api";

export default function InboxComWebSocket({ reload }) {
    const [aba, setAba] = useState("inbox");
    const [mensagens, setMensagens] = useState([]);
    const [selected, setSelected] = useState(null);
    const [loading, setLoading] = useState(true);
    const [painelMinimizado, setPainelMinimizado] = useState(false);
    const [tocando, setTocando] = useState(false);
    const [duracao, setDuracao] = useState("0:00");

    //  Conectar ao WebSocket
    const { isConnected, isLoading: wsLoading } = useVoiceMailWebSocket({
        url: "ws://localhost:8080/ws/voicemails",

        // Quando um novo voicemail chega
        onNewVoiceMail: (novoVoicemail) => {
            console.log(" Novo voicemail recebido via WebSocket:", novoVoicemail);
            setMensagens((prev) => [novoVoicemail, ...prev]);
        },

        // Quando um voicemail é marcado como ouvido
        onVoiceMailUpdated: (update) => {
            console.log(" Voicemail atualizado:", update);
            setMensagens((prev) =>
                prev.map((m) =>
                    m.id === update.voiceMailId
                        ? { ...m, ouvido: update.ouvido }
                        : m
                )
            );

            // Atualizar o painel de detalhes se estiver aberto
            if (selected?.id === update.voiceMailId) {
                setSelected((prev) => ({
                    ...prev,
                    ouvido: update.ouvido,
                }));
            }
        },

        // Quando um voicemail é deletado
        onVoiceMailDeleted: (deletion) => {
            console.log("️ Voicemail deletado:", deletion);
            setMensagens((prev) =>
                prev.filter((m) => m.id !== deletion.voiceMailId)
            );

            // Fechar painel de detalhes se estiver aberto
            if (selected?.id === deletion.voiceMailId) {
                setSelected(null);
                setPainelMinimizado(false);
                setTocando(false);
            }
        },
    });

    // Carregar mensagens iniciais
    async function carregar() {
        setLoading(true);
        const data = await listarVoicemails();
        setMensagens(data);
        setSelected(null);
        setPainelMinimizado(false);
        setTocando(false);
        setLoading(false);
    }

    useEffect(() => {
        carregar();
    }, [reload]);

    // ... resto do código do componente permanece igual ...

    // Indicador visual de conexão WebSocket
    const connectionIndicator = (
        <div className="ws-indicator" style={{
            position: "fixed",
            bottom: "20px",
            right: "20px",
            display: "flex",
            alignItems: "center",
            gap: "8px",
            padding: "8px 12px",
            backgroundColor: isConnected ? "#4ade80" : "#ef4444",
            color: "white",
            borderRadius: "20px",
            fontSize: "12px",
            fontWeight: "bold",
        }}>
            <span style={{
                width: "8px",
                height: "8px",
                backgroundColor: "white",
                borderRadius: "50%",
                display: "inline-block",
                animation: isConnected ? "pulse 1s infinite" : "none"
            }}></span>
            {isConnected ? "WebSocket Conectado" : "WebSocket Desconectado"}
        </div>
    );

    // ... retornar JSX com connectionIndicator incluído ...

    return (
        <main className="app-shell">
            {connectionIndicator}
            {/* ... resto do JSX ... */}
        </main>
    );
}

/**
 * ALTERNATIVAMENTE, use este trecho modificado no seu Inbox.jsx atual:
 * 
 * 1. Importe o hook no topo do arquivo:
 *    import useVoiceMailWebSocket from "../hooks/useVoiceMailWebSocket";
 * 
 * 2. Adicione logo após os estados existentes:
 *    const { isConnected } = useVoiceMailWebSocket({
 *        url: "ws://localhost:8080/ws/voicemails",
 *        onNewVoiceMail: (novo) => setMensagens([novo, ...mensagens]),
 *        onVoiceMailUpdated: (update) => setMensagens(prev =>
 *            prev.map(m => m.id === update.voiceMailId 
 *                ? {...m, ouvido: update.ouvido} : m)
 *        ),
 *        onVoiceMailDeleted: (del) => {
 *            setMensagens(prev => prev.filter(m => m.id !== del.voiceMailId));
 *            if (selected?.id === del.voiceMailId) setSelected(null);
 *        }
 *    });
 * 
 * 3. Pronto! Agora você tem sincronização em tempo real.
 */

import { useEffect, useState, useRef } from 'react';

/**
 * Hook customizado para gerenciar conexão WebSocket com o servidor
 * @param {string} url - URL do WebSocket (ex: ws://localhost:8080/ws/voicemails)
 * @param {function} onNewVoiceMail - Callback para novo voicemail
 * @param {function} onVoiceMailUpdated - Callback para voicemail atualizado
 * @param {function} onVoiceMailDeleted - Callback para voicemail deletado
 * @returns {object} estado e funções da conexão WebSocket
 */
export const useVoiceMailWebSocket = ({
    url = 'ws://localhost:8080/ws/voicemails',
    onNewVoiceMail,
    onVoiceMailUpdated,
    onVoiceMailDeleted,
} = {}) => {
    const [isConnected, setIsConnected] = useState(false);
    const [isLoading, setIsLoading] = useState(true);
    const wsRef = useRef(null);

    useEffect(() => {
        const ws = new WebSocket(url);

        ws.onopen = () => {
            console.log('✅ Conectado ao servidor WebSocket');
            setIsConnected(true);
            setIsLoading(false);
        };

        ws.onmessage = (event) => {
            try {
                const message = JSON.parse(event.data);
                console.log(' Mensagem recebida:', message);

                switch (message.type) {
                    case 'CONNECTED':
                        console.log('✓', message.message);
                        break;

                    case 'NEW_VOICEMAIL':
                        console.log(' Novo voicemail chegou');
                        onNewVoiceMail?.(message.data);
                        break;

                    case 'VOICEMAIL_UPDATED':
                        console.log(' Voicemail atualizado:', message.data);
                        onVoiceMailUpdated?.(message.data);
                        break;

                    case 'VOICEMAIL_DELETED':
                        console.log('️ Voicemail deletado:', message.data);
                        onVoiceMailDeleted?.(message.data);
                        break;

                    default:
                        console.warn('Tipo de mensagem desconhecido:', message.type);
                }
            } catch (error) {
                console.error('Erro ao processar mensagem WebSocket:', error);
            }
        };

        ws.onerror = (error) => {
            console.error('❌ Erro WebSocket:', error);
            setIsConnected(false);
        };

        ws.onclose = () => {
            console.log(' Desconectado do servidor');
            setIsConnected(false);
            setIsLoading(false);

            // Tentar reconectar após 3 segundos
            setTimeout(() => {
                console.log(' Tentando reconectar...');
            }, 3000);
        };

        wsRef.current = ws;

        return () => {
            if (ws.readyState === WebSocket.OPEN) {
                ws.close();
            }
        };
    }, [url, onNewVoiceMail, onVoiceMailUpdated, onVoiceMailDeleted]);

    return {
        isConnected,
        isLoading,
        send: (message) => {
            if (wsRef.current?.readyState === WebSocket.OPEN) {
                wsRef.current.send(JSON.stringify(message));
            } else {
                console.warn('WebSocket não está conectado');
            }
        },
    };
};

export default useVoiceMailWebSocket;
